import test from 'node:test';
import assert from 'node:assert/strict';
import { DatabaseSync } from 'node:sqlite';
import { readFileSync, readdirSync } from 'node:fs';
import { handleApi } from '../server/api.ts';
import { handleMcp } from '../server/mcp.ts';
import { freshness, nextReminderDue, scaledIngredients } from '../server/domain.ts';
import { MAX_HOUSEHOLD_RECORDS } from '../shared/record-limits.ts';
class Database {
 constructor(){this.db=new DatabaseSync(':memory:');for(const f of readdirSync(new URL('../drizzle/',import.meta.url)).filter(f=>f.endsWith('.sql')).sort())this.db.exec(readFileSync(new URL('../drizzle/'+f,import.meta.url),'utf8'));}
 prepare(sql){return new Statement(this.db,sql);}
 async batch(statements){this.db.exec('BEGIN');try{const results=[];for(const s of statements)results.push(await s.run());this.db.exec('COMMIT');return results;}catch(e){this.db.exec('ROLLBACK');throw e;}}
}
class Statement {
 constructor(db,sql,values=[]){this.db=db;this.sql=sql;this.values=values;}
 bind(...values){return new Statement(this.db,this.sql,values);}
 async first(){return this.db.prepare(this.sql).get(...this.values)??null;}
 async all(){return{results:this.db.prepare(this.sql).all(...this.values),success:true};}
 async run(){const r=this.db.prepare(this.sql).run(...this.values);return{success:true,meta:{changes:r.changes}};}
}
function setup(options={}){const DB=new Database();const env={DB,...options};const call=async(path,method='GET',data,opts={})=>{const headers={'oai-authenticated-user-id':opts.user??'owner','Origin':opts.origin??'https://hub.test','Content-Type':'application/json','Idempotency-Key':opts.key??crypto.randomUUID()};if(opts.email)headers['oai-authenticated-user-email']=opts.email;if(opts.anonymous)delete headers['oai-authenticated-user-id'];const res=await handleApi(new Request('https://hub.test'+path,{method,headers,body:data===undefined?undefined:JSON.stringify(data)}),env);return{status:res.status,data:await res.json()};};return{DB,call,env};}
const recipe={title:'Soup',servings:4,instructions:'Cook.',ingredients:[{name:'Carrots',amount:200,unit:'g'},{name:'Carrots',amount:50,unit:'g'},{name:'Milk',amount:100,unit:'ml'},{name:'Milk',amount:20,unit:'g'},{name:'Salt'}]};
test('authentication, membership and same-origin writes are enforced',async()=>{const{call}=setup();assert.equal((await call('/api/state','GET',undefined,{anonymous:true})).status,401);assert.equal((await call('/api/state')).status,200);assert.equal((await call('/api/state','GET',undefined,{user:'outsider'})).status,403);assert.equal((await call('/api/items','POST',{kind:'shopping',data:{title:'Milk'}},{origin:'https://other.test'})).status,403);assert.equal((await call('/api/members','POST',{userId:'member',displayName:'Family'})).status,200);assert.equal((await call('/api/state','GET',undefined,{user:'member'})).status,200);assert.equal((await call('/api/admin','GET',undefined,{user:'member'})).status,403);});
test('create is idempotent, checkbox writes persist across devices and stale versions cannot overwrite',async()=>{const{call}=setup();const payload={kind:'shopping',data:{title:'Milk',listName:'Groceries',done:false}};const first=await call('/api/items','POST',payload,{key:'same-create-key'});assert.equal(first.status,201);const second=await call('/api/items','POST',payload,{key:'same-create-key'});assert.equal(second.data.record.id,first.data.record.id);assert.equal((await call('/api/state')).data.records.length,1);assert.equal((await call('/api/items','POST',{...payload,data:{title:'Other'}},{key:'same-create-key'})).status,409);const id=first.data.record.id;const changed=await call('/api/items/'+id,'PATCH',{version:1,data:{done:true}});assert.equal(changed.data.record.version,2);assert.equal(changed.data.record.data.done,true);assert.equal((await call('/api/items/'+id,'PATCH',{version:1,data:{done:false}})).status,409);assert.equal((await call('/api/state')).data.records[0].data.done,true);});
test('meal snapshots survive recipe editing and deletion; pantry filtering and scaled imports are idempotent',async()=>{const{call}=setup();const r=(await call('/api/items','POST',{kind:'recipe',data:recipe})).data.record;const meal=(await call('/api/items','POST',{kind:'meal',data:{day:'2026-10-29',slot:'dinner',recipeId:r.id,servings:8}})).data.record;assert.equal(meal.data.recipeSnapshot.title,'Soup');await call('/api/items/'+r.id,'PATCH',{version:1,data:{title:'Changed'}});await call('/api/items/'+r.id,'DELETE',{version:2});const request={listName:'Weekend',excludedIngredientNames:['Salt']};const first=await call('/api/meals/'+meal.id+'/ingredients','POST',request,{key:'meal-import-once'});assert.equal(first.status,200);assert.equal(first.data.importedCount,3);assert.deepEqual(first.data.records.map(r=>r.data.quantity),['500 g','200 ml','40 g']);await call('/api/meals/'+meal.id+'/ingredients','POST',request,{key:'meal-import-once'});assert.equal((await call('/api/state')).data.records.filter(r=>r.kind==='shopping').length,3);const reopened=await call('/api/meals/'+meal.id+'/ingredients','POST',request,{key:'a-fresh-http-key'});assert.equal(reopened.data.importedCount,3);assert.equal((await call('/api/state')).data.records.filter(r=>r.kind==='shopping').length,3);assert.equal((await call('/api/items','POST',{kind:'meal',data:{day:'2026-10-29',slot:'dinner',title:'Duplicate'}})).status,409);});
test('admin workflow results never enter household state or household export',async()=>{const{call}=setup();const data={workflow:'news',sourceId:'source-a',summary:'Owner private report',observedAt:'2026-10-29T10:00:00Z',runStatus:'ready'};assert.equal((await call('/api/admin/results/result-a','PUT',{data})).status,200);assert.equal((await call('/api/admin')).data.results[0].summary,'Owner private report');assert.equal((await call('/api/state')).data.records.length,0);assert.equal(JSON.stringify((await call('/api/export')).data).includes('Owner private report'),false);assert.equal((await call('/api/admin/results/result-a','PUT',{version:1,data:{...data,workflow:'other'}})).status,409);assert.equal((await call('/api/admin/results/result-a','PUT',{version:1,data:{...data,summary:'Updated'}})).data.result.version,2);assert.equal((await call('/api/admin/results/result-a','PUT',{version:1,data})).status,409);});
test('payload bounds and schema allowlists prevent image bytes from being persisted',async()=>{const{call,DB}=setup();const r=await call('/api/items','POST',{kind:'recipe',data:{...recipe,image:'data:image/jpeg;base64,private',photo:'private'}});assert.equal(r.status,201);const row=await DB.prepare('SELECT data FROM hub_records WHERE id=?').bind(r.data.record.id).first();assert.equal(row.data.includes('private'),false);assert.equal((await call('/api/items','POST',{kind:'recipe',data:{...recipe,instructions:'x'.repeat(110000)}})).status,413);assert.equal((await call('/api/items','POST',{kind:'source',data:{title:'Link',sourceId:'x',sourceLink:'javascript:alert(1)'}})).status,400);assert.equal((await call('/api/items','POST',{kind:'calendar',data:{title:'Bad date',startAt:'2026-02-31',endAt:'2026-03-05'}})).status,400);});
test('freshness thresholds, quantity dimensions and monthly recurrence boundaries',()=>{const now=Date.parse('2026-10-29T12:00:00Z');assert.equal(freshness('2026-10-29T11:00:00Z',now),'green');assert.equal(freshness('2026-10-29T10:59:59Z',now),'yellow');assert.equal(freshness('2026-10-28T12:00:00Z',now),'yellow');assert.equal(freshness('2026-10-28T11:59:59Z',now),'red');assert.equal(freshness(undefined,now),'unknown');assert.equal(freshness('2026-10-30T12:00:00Z',now),'unknown');assert.equal(nextReminderDue('2026-01-31','monthly'),'2026-02-28');assert.equal(nextReminderDue('2028-01-31','monthly'),'2028-02-29');assert.deepEqual(scaledIngredients(recipe,2,['Salt']).map(x=>[x.name,x.amount,x.unit]),[['Carrots',125,'g'],['Milk',50,'ml'],['Milk',10,'g']]);});

test('deleted items and ingredients stay deleted when original operations replay',async()=>{const{call}=setup();const data={kind:'shopping',data:{title:'Milk'}};const r=(await call('/api/items','POST',data,{key:'delete-replay-key'})).data.record;await call('/api/items/'+r.id,'DELETE',{version:1});assert.equal((await call('/api/items','POST',data,{key:'delete-replay-key'})).status,410);assert.equal((await call('/api/state')).data.records.length,0);const recipeRow=(await call('/api/items','POST',{kind:'recipe',data:recipe})).data.record;const meal=(await call('/api/items','POST',{kind:'meal',data:{day:'2026-10-30',recipeId:recipeRow.id,slot:'dinner'}})).data.record;const imported=await call('/api/meals/'+meal.id+'/ingredients','POST',{}, {key:'delete-ingredient-replay'});const item=imported.data.records[0];await call('/api/items/'+item.id,'DELETE',{version:1});const again=await call('/api/meals/'+meal.id+'/ingredients','POST',{}, {key:'delete-ingredient-replay'});assert.equal(again.data.importedCount,imported.data.importedCount-1);});
test('MCP fixed tools enforce platform identity, owner membership and admin result isolation',async()=>{const{DB,call}=setup();await call('/api/state');const invoke=async(method,params,who='owner')=>{const h={'Content-Type':'application/json'};if(who)h['oai-authenticated-user-id']=who;const res=await handleMcp(new Request('https://hub.test/mcp',{method:'POST',headers:h,body:JSON.stringify({jsonrpc:'2.0',id:1,method,params})}),{DB});return{status:res.status,data:await res.json()};};assert.equal((await invoke('tools/list',{},null)).status,401);assert.equal((await invoke('tools/list',{},'stranger')).status,403);assert.equal((await invoke('server/discover',{})).data.result.supportedVersions[0],'2026-07-28');assert.equal((await invoke('tools/list',{})).data.result.tools.length,10);const source={name:'bird_hub_upsert_result',arguments:{id:'news-result',data:{workflow:'news',sourceId:'briefing',summary:'Verified result',observedAt:'2026-10-29T12:00:00Z',runStatus:'ready'}}};assert.equal((await invoke('tools/call',source)).data.result.isError,false);assert.equal((await invoke('tools/call',{name:'bird_hub_read_household',arguments:{}})).data.result.structuredContent.records.length,0);assert.equal((await invoke('tools/call',{name:'bird_hub_read_admin_results',arguments:{}})).data.result.structuredContent.results[0].summary,'Verified result');assert.equal((await invoke('tools/call',{name:'arbitrary_proxy',arguments:{url:'https://example.com'}})).data.error.code,-32602);});

test('saved recipes send pantry-filtered ingredients straight to shopping without a meal plan',async()=>{const{call}=setup();const r=(await call('/api/items','POST',{kind:'recipe',data:recipe})).data.record;const one=await call('/api/recipes/'+r.id+'/ingredients','POST',{listName:'Direct',servings:2,excludedIngredientNames:['Milk','Salt']},{key:'direct-recipe-import'});assert.equal(one.status,200);assert.equal(one.data.importedCount,1);assert.equal(one.data.records[0].data.quantity,'125 g');const two=await call('/api/recipes/'+r.id+'/ingredients','POST',{listName:'Direct',servings:2,excludedIngredientNames:['Salt','Milk']},{key:'another-direct-key'});assert.equal(two.data.importedCount,1);assert.equal((await call('/api/state')).data.records.filter(r=>r.kind==='shopping').length,1);});

test('email-bound invitation admits only the verified recipient and never demotes the owner',async()=>{const{call}=setup();await call('/api/state','GET',undefined,{email:'owner@example.test'});const invite=await call('/api/members/invites','POST',{email:' Partner@Example.Test ',displayName:'Partner'});assert.equal(invite.status,200);assert.equal((await call('/api/state','GET',undefined,{user:'partner-id',email:'wrong@example.test'})).status,403);const accepted=await call('/api/state','GET',undefined,{user:'partner-id',email:'PARTNER@example.test'});assert.equal(accepted.status,200);assert.equal(accepted.data.permissions.admin,false);assert.equal((await call('/api/admin','GET',undefined,{user:'partner-id',email:'partner@example.test'})).status,403);assert.equal((await call('/api/members/invites','POST',{email:'another@example.test',displayName:'Another'},{user:'partner-id',email:'partner@example.test'})).status,403);assert.equal((await call('/api/items','POST',{kind:'source',data:{title:'Forged',sourceId:'fake',runStatus:'ready'}},{user:'partner-id',email:'partner@example.test'})).status,403);await call('/api/members/invites','POST',{email:'owner@example.test',displayName:'Accidental owner invite'});assert.equal((await call('/api/state','GET',undefined,{email:'owner@example.test'})).data.permissions.admin,true);});

test('owner runtime bootstrap validates and imports once without overwriting newer results or exposing admin data',async()=>{const{call,DB,env}=setup();await call('/api/state');await call('/api/members','POST',{userId:'member',displayName:'Member'});const existing={workflow:'news',sourceId:'existing',summary:'Newer report already saved',observedAt:'2026-10-29T12:00:00Z',runStatus:'ready'};await call('/api/admin/results/existing-result','PUT',{data:existing});const config={batchId:'initial-runtime-import',invites:[{email:'Partner@Example.Test',displayName:'Partner'}],sources:[{id:'source-news',data:{title:'News',sourceId:'news',runStatus:'ready',lastSuccess:'2026-10-29T06:00:00Z'}}],results:[{id:'imported-result',data:{workflow:'events',sourceId:'events-watch',summary:'Verified initial snapshot',observedAt:'2026-10-29T10:00:00Z',runStatus:'ready'}},{id:'existing-result',data:{...existing,summary:'Old bootstrap report'}}]};env.HUB_BOOTSTRAP_JSON=JSON.stringify(config);const member=await call('/api/state','GET',undefined,{user:'member'});assert.equal(member.status,200);assert.equal(member.data.records.length,0);assert.equal(await DB.prepare("SELECT COUNT(*) AS n FROM hub_operations WHERE operation_key LIKE 'bootstrap:%'").first().then(r=>r.n),0);const owner=await call('/api/state');assert.equal(owner.data.records.length,1);assert.equal(JSON.stringify(owner.data).includes('Verified initial snapshot'),false);assert.equal(JSON.stringify(owner.data).includes('Partner@Example.Test'),false);let admin=(await call('/api/admin')).data.results;assert.equal(admin.find(r=>r.id==='existing-result').summary,'Newer report already saved');const imported=admin.find(r=>r.id==='imported-result');await call('/api/admin/results/imported-result','PUT',{version:imported.version,data:{...config.results[0].data,summary:'A later workflow result'}});await call('/api/state');admin=(await call('/api/admin')).data.results;assert.equal(admin.find(r=>r.id==='imported-result').summary,'A later workflow result');assert.equal((await call('/api/state','GET',undefined,{user:'partner',email:'partner@example.test'})).status,200);assert.equal((await call('/api/admin','GET',undefined,{user:'partner',email:'partner@example.test'})).status,403);assert.equal(await DB.prepare("SELECT COUNT(*) AS n FROM hub_operations WHERE operation_key LIKE 'bootstrap:%'").first().then(r=>r.n),1);});
test('malformed runtime bootstrap fails safely and applies no partial import',async()=>{const{call,DB,env}=setup();await call('/api/state');env.HUB_BOOTSTRAP_JSON=JSON.stringify({batchId:'bad-bootstrap',invites:[{email:'sensitive@example.test',displayName:'Private'}],sources:[{id:'bad-source',data:{title:'Bad',sourceId:'x',sourceLink:'javascript:alert(1)'}}]});const r=await call('/api/state');assert.equal(r.status,503);assert.equal(JSON.stringify(r.data).includes('sensitive@example.test'),false);assert.equal(await DB.prepare('SELECT COUNT(*) AS n FROM hub_invites').first().then(r=>r.n),0);assert.equal(await DB.prepare("SELECT COUNT(*) AS n FROM hub_operations WHERE operation_key LIKE 'bootstrap:%'").first().then(r=>r.n),0);});

test('household feed is shared, admin remains private, workflow ownership and versions are enforced',async()=>{const{call}=setup();await call('/api/state');await call('/api/members','POST',{userId:'member',displayName:'Member'});const data={workflow:'news',sourceId:'morning-news',title:'Today’s news',summary:'A family-safe daily summary',observedAt:'2026-10-29T12:00:00Z',runStatus:'ready'};await call('/api/admin/results/private-news','PUT',{data:{...data,summary:'Private admin details'}});assert.equal((await call('/api/household-feed/home-news','PUT',{data})).status,200);const member=(await call('/api/state','GET',undefined,{user:'member'})).data;assert.equal(member.householdFeed[0].summary,data.summary);assert.equal(JSON.stringify(member).includes('Private admin details'),false);assert.equal((await call('/api/household-feed/home-news','PUT',{version:1,data:{...data,summary:'Unauthorized'}},{user:'member'})).status,403);assert.equal((await call('/api/household-feed/home-news','PUT',{version:1,data:{...data,workflow:'other'}})).status,409);assert.equal((await call('/api/household-feed/home-news','PUT',{version:1,data:{...data,summary:'New safe update'}})).data.feed.version,2);assert.equal((await call('/api/household-feed/home-news','PUT',{version:1,data})).status,409);});
test('per-source receiving controls preserve last success, run health and verified paused schedule',async()=>{const{call}=setup();await call('/api/state');await call('/api/members','POST',{userId:'member',displayName:'Member'});const data={title:'Existing paused task',sourceId:'task-source',adapter:'workflow',runStatus:'paused',lastSuccess:'2026-10-28T12:00:00Z',schedulePaused:true,scheduleLabel:'Paused weekly task'};const source=(await call('/api/items','POST',{kind:'source',data})).data.record;assert.equal((await call('/api/sources/'+source.id+'/connection','POST',{enabled:true,version:1},{user:'member'})).status,403);const toggle=await call('/api/sources/'+source.id+'/connection','POST',{enabled:true,version:1});assert.equal(toggle.data.record.data.connectionEnabled,true);assert.equal(toggle.data.record.data.lastSuccess,data.lastSuccess);assert.equal(toggle.data.record.data.runStatus,'paused');assert.equal(toggle.data.record.data.schedulePaused,true);assert.ok(toggle.data.record.data.connectionConfiguredAt);assert.equal((await call('/api/sources/'+source.id+'/connection','POST',{enabled:false,version:1})).status,409);const manual=(await call('/api/items','POST',{kind:'source',data:{title:'Unlinked',sourceId:'manual'}})).data.record;assert.equal((await call('/api/sources/'+manual.id+'/connection','POST',{enabled:true,version:1})).status,409);});
test('runtime household projections and receiving configs import once without replacing newer household content',async()=>{const{call,env}=setup();await call('/api/state');const source=(await call('/api/items','POST',{kind:'source',data:{title:'News',sourceId:'news-source',runStatus:'stale',lastSuccess:'2026-10-28T06:00:00Z'}})).data.record;const data={workflow:'news',sourceId:'news-source',title:'Dated briefing',body:'Safe family briefing',observedAt:'2026-10-29T06:00:00Z',runStatus:'ready'};env.HUB_BOOTSTRAP_JSON=JSON.stringify({batchId:'household-projection-import',householdFeed:[{id:'dated-news',data}],sourceConfigurations:[{id:source.id,adapter:'workflow',connectionEnabled:true,scheduleLabel:'Daily at 06:00',schedulePaused:false}]});let state=(await call('/api/state')).data;assert.equal(state.householdFeed[0].body,data.body);let saved=state.records.find(r=>r.id===source.id);assert.equal(saved.data.connectionEnabled,true);assert.equal(saved.data.scheduleLabel,'Daily at 06:00');assert.equal(saved.data.schedulePaused,false);assert.equal(saved.data.runStatus,'stale');assert.equal(saved.data.lastSuccess,'2026-10-28T06:00:00Z');await call('/api/sources/'+source.id+'/connection','POST',{enabled:false,version:saved.version});await call('/api/household-feed/dated-news','PUT',{version:1,data:{...data,body:'Newer family update'}});state=(await call('/api/state')).data;assert.equal(state.householdFeed[0].body,'Newer family update');assert.equal(state.records.find(r=>r.id===source.id).data.connectionEnabled,false);});
test('MCP household publishing respects persisted per-source receiving without changing schedules',async()=>{const{DB,call}=setup();await call('/api/state');const source=(await call('/api/items','POST',{kind:'source',data:{title:'Morning news',sourceId:'news-projection',adapter:'workflow',runStatus:'stale',lastSuccess:'2026-10-28T06:00:00Z',schedulePaused:false,scheduleLabel:'Daily at 06:00 Europe/London'}})).data.record;const publish=async(version,summary)=>{const response=await handleMcp(new Request('https://hub.test/mcp',{method:'POST',headers:{'Content-Type':'application/json','oai-authenticated-user-id':'owner'},body:JSON.stringify({jsonrpc:'2.0',id:1,method:'tools/call',params:{name:'bird_hub_upsert_household_feed',arguments:{id:'news-home',version,data:{workflow:'news',sourceId:'news-projection',title:'Today’s news',summary,observedAt:'2026-10-29T06:00:00Z',runStatus:'ready'}}}})}),{DB});return(await response.json()).result;};assert.equal((await publish(undefined,'Initial update')).isError,true);let configured=(await call('/api/sources/'+source.id+'/connection','POST',{enabled:true,version:1})).data.record;assert.equal((await publish(undefined,'Initial update')).isError,false);assert.equal((await publish(1,'Fresh family update')).isError,false);await call('/api/sources/'+source.id+'/connection','POST',{enabled:false,version:configured.version});assert.equal((await publish(2,'Must not publish')).isError,true);const state=(await call('/api/state')).data;assert.equal(state.householdFeed[0].summary,'Fresh family update');assert.equal(state.records.find(r=>r.id===source.id).data.lastSuccess,'2026-10-28T06:00:00Z');assert.equal(state.records.find(r=>r.id===source.id).data.scheduleLabel,'Daily at 06:00 Europe/London');});

function appleFixture(){let fail=false;let empty=false;let calls=0;const calendar='https://p01-caldav.icloud.com/123/calendars/family/';const rows=props=>'<d:multistatus xmlns:d="DAV:" xmlns:c="urn:ietf:params:xml:ns:caldav" xmlns:a="http://apple.com/ns/ical/"><d:response><d:href>'+calendar+'</d:href><d:propstat><d:prop>'+props+'</d:prop><d:status>HTTP/1.1 200 OK</d:status></d:propstat></d:response></d:multistatus>';const day=new Date().toISOString().slice(0,10).replaceAll('-','');const ics=['BEGIN:VCALENDAR','VERSION:2.0','BEGIN:VEVENT','UID:family-event-1','DTSTART:'+day+'T120000Z','DTEND:'+day+'T130000Z','SUMMARY:Family outing','END:VEVENT','END:VCALENDAR'].join('\r\n');const fetcher=async(url,init)=>{calls++;if(fail)return new Response('',{status:401});if(init.method==='REPORT')return new Response(empty?'<d:multistatus xmlns:d="DAV:"/>':rows('<c:calendar-data><![CDATA['+ics+']]></c:calendar-data>'),{status:207});if(init.body.includes('current-user-principal'))return new Response(rows('<d:current-user-principal><d:href>https://p01-caldav.icloud.com/123/principal/</d:href></d:current-user-principal>'),{status:207});if(init.body.includes('calendar-home-set'))return new Response(rows('<c:calendar-home-set><d:href>https://p01-caldav.icloud.com/123/calendars/</d:href></c:calendar-home-set>'),{status:207});return new Response(rows('<d:displayname>Family</d:displayname><d:resourcetype><c:calendar/></d:resourcetype><a:calendar-color>#12AB34</a:calendar-color>'),{status:207});};return{calendar,fetcher,get calls(){return calls},set fail(v){fail=v},set empty(v){empty=v}};}
test('iCloud private connection encrypts credentials, enforces owner/origin and imports read-only authoritative events',async()=>{const apple=appleFixture();const encryptionKey=Buffer.alloc(32,17).toString('base64');const{DB,call,env}=setup({HUB_ENCRYPTION_KEY:encryptionKey,ICLOUD_FETCH:apple.fetcher});await call('/api/state');await call('/api/members','POST',{userId:'member',displayName:'Member'});const credentials={username:'apple-owner@example.test',password:'synthetic-app-specific-password'};assert.equal((await call('/api/icloud/status','GET',undefined,{user:'member'})).data.configured,false);assert.equal((await call('/api/icloud/connect','POST',credentials,{origin:'https://bad.test'})).status,403);const connected=await call('/api/icloud/connect','POST',credentials);assert.equal(connected.status,200);assert.equal(connected.data.username,credentials.username);assert.equal(connected.data.calendars[0].id,apple.calendar);assert.equal(JSON.stringify(connected.data).includes(credentials.password),false);const config=await DB.prepare('SELECT * FROM hub_icloud_accounts WHERE user_id=\'owner\'').first();assert.equal(JSON.stringify(config).includes(credentials.username),false);assert.equal(JSON.stringify(config).includes(credentials.password),false);assert.equal((await call('/api/icloud/calendars','POST',{calendarIds:['https://attacker.test/calendar']})).status,400);assert.equal((await call('/api/icloud/calendars','POST',{calendarIds:[apple.calendar]})).status,200);const manual=(await call('/api/items','POST',{kind:'calendar',data:{title:'Manual plan',startAt:new Date().toISOString(),endAt:new Date().toISOString()}})).data.record;const synced=await call('/api/icloud/sync','POST',{});assert.equal(synced.status,200);assert.equal(synced.data.importedCount,1);let state=(await call('/api/state')).data;const imported=state.records.find(r=>r.data.origin==='icloud');assert.equal(imported.data.title,'Family outing');assert.equal(imported.data.calendarTitle,'Family');assert.equal(state.integrations.icloud.configured,true);assert.equal(state.integrations.icloud.selectedCount,1);assert.equal(JSON.stringify(state).includes(credentials.username),false);assert.equal(JSON.stringify((await call('/api/export')).data).includes(credentials.password),false);assert.equal((await call('/api/items/'+imported.id,'PATCH',{version:imported.version,data:{title:'Edit imported'}})).status,403);assert.equal((await call('/api/items/'+imported.id,'DELETE',{version:imported.version})).status,403);assert.equal((await call('/api/items','POST',{kind:'calendar',data:{title:'Fake import',startAt:new Date().toISOString(),origin:'icloud'}})).status,403);const lastGood=state.integrations.icloud.lastSuccess;apple.fail=true;assert.equal((await call('/api/icloud/sync','POST',{})).status,502);state=(await call('/api/state')).data;assert.equal(state.integrations.icloud.lastSuccess,lastGood);assert.ok(state.records.find(r=>r.id===imported.id));apple.fail=false;apple.empty=true;const emptied=await call('/api/icloud/sync','POST',{});assert.equal(emptied.status,200);assert.equal(emptied.data.removedCount,1);state=(await call('/api/state')).data;assert.ok(state.records.find(r=>r.id===manual.id));assert.equal(state.records.some(r=>r.data.origin==='icloud'),false);const disconnected=await call('/api/icloud/config','DELETE',{removeImported:true});assert.equal(disconnected.status,200);assert.equal(await DB.prepare('SELECT COUNT(*) AS n FROM hub_icloud_accounts').first().then(x=>x.n),0);assert.ok((await call('/api/state')).data.records.find(r=>r.id===manual.id));});
