test('calendar API persists and syncs 32 selected calendars rather than silently truncating to eight',async()=>{const calendars=Array.from({length:32},(_,i)=>({id:'https://p01-caldav.icloud.com/123/calendars/c-'+i+'/',displayName:'Calendar '+i}));let reports=0;const wrap=children=>'<d:multistatus xmlns:d="DAV:" xmlns:c="urn:ietf:params:xml:ns:caldav">'+children+'</d:multistatus>';const entry=(href,properties)=>'<d:response><d:href>'+href+'</d:href><d:propstat><d:prop>'+properties+'</d:prop><d:status>HTTP/1.1 200 OK</d:status></d:propstat></d:response>';const fetcher=async(raw,init)=>{if(init.method==='REPORT'){reports++;return new Response(wrap(''),{status:207});}if(init.body.includes('current-user-principal'))return new Response(wrap(entry('/','<d:current-user-principal><d:href>/123/principal/</d:href></d:current-user-principal>')),{status:207});if(init.body.includes('calendar-home-set'))return new Response(wrap(entry('/','<c:calendar-home-set><d:href>https://p01-caldav.icloud.com/123/calendars/</d:href></c:calendar-home-set>')),{status:207});return new Response(wrap(calendars.map(c=>entry(c.id,'<d:displayname>'+c.displayName+'</d:displayname><d:resourcetype><c:calendar/></d:resourcetype>')).join('')),{status:207});};const{call}=setup({HUB_ENCRYPTION_KEY:Buffer.alloc(32,77).toString('base64'),ICLOUD_FETCH:fetcher});assert.equal((await call('/api/icloud/connect','POST',{username:'owner@example.test',password:'synthetic-password'})).status,200);assert.equal((await call('/api/icloud/calendars','POST',{calendarIds:calendars.map(c=>c.id)})).status,200);assert.equal((await call('/api/icloud/status')).data.selectedCalendarIds.length,32);assert.equal((await call('/api/icloud/sync','POST',{})).status,200);assert.equal(reports,32);assert.equal((await call('/api/state')).data.integrations.icloud.selectedCount,32);assert.equal((await call('/api/icloud/calendars','POST',{calendarIds:[...calendars.map(c=>c.id),calendars[0].id]})).status,400);});
test('successful subscription link replacement keeps opaque identity and profile, with stale updates rejected',async()=>{const feed=subscriptionFixture();const{call,DB}=setup({HUB_ENCRYPTION_KEY:Buffer.alloc(32,78).toString('base64'),CALENDAR_FEED_FETCH:feed.fetcher,CALENDAR_FEED_RESOLVE:feed.resolve});const person=(await call('/api/items','POST',{kind:'profile',data:{name:'Session person',color:'#123456'}})).data.record;const added=await call('/api/icloud/subscriptions','POST',{title:'Sessions',url:feed.privateUrl,personId:person.id});const previous=added.data.subscriptions[0],record=(await call('/api/state')).data.records.find(r=>r.kind==='calendar'),encrypted=(await DB.prepare('SELECT encrypted_url FROM hub_calendar_subscriptions').first()).encrypted_url;const nextUrl=feed.privateUrl.replace('synthetic-private-token','replacement-private-token');const replaced=await call('/api/icloud/subscriptions/'+previous.id,'POST',{title:'Updated sessions',url:nextUrl,version:previous.version});assert.equal(replaced.status,200);assert.equal(replaced.data.subscriptions.length,1);assert.equal(replaced.data.subscriptions[0].id,previous.id);assert.equal(replaced.data.subscriptions[0].personId,person.id);assert.notEqual((await DB.prepare('SELECT encrypted_url FROM hub_calendar_subscriptions').first()).encrypted_url,encrypted);const state=(await call('/api/state')).data;assert.equal(state.records.find(r=>r.kind==='calendar').id,record.id);assert.equal(JSON.stringify(state).includes('synthetic-private-token'),false);assert.equal(JSON.stringify(state).includes('replacement-private-token'),false);const calls=feed.calls;assert.equal((await call('/api/icloud/subscriptions/'+previous.id,'POST',{title:'Stale edit',url:nextUrl,version:previous.version})).status,409);assert.equal(feed.calls,calls);assert.equal((await call('/api/icloud/subscriptions/'+previous.id,'DELETE',{removeImported:true,version:previous.version})).status,409);assert.equal(await DB.prepare('SELECT COUNT(*) AS n FROM hub_calendar_subscriptions').first().then(r=>r.n),1);});
test('public subscription names redact equivalent mixed-case webcal and HTML-encoded private links',async()=>{const feed=subscriptionFixture('redacted-label','&owner=one');const{call}=setup({HUB_ENCRYPTION_KEY:Buffer.alloc(32,79).toString('base64'),CALENDAR_FEED_FETCH:feed.fetcher,CALENDAR_FEED_RESOLVE:feed.resolve});const variant=feed.privateUrl.replace('https://calendar.example.org','WEBcal://CALENDAR.EXAMPLE.ORG').replaceAll('&','&amp;');const added=await call('/api/icloud/subscriptions','POST',{title:'Sessions '+variant,url:feed.privateUrl});assert.equal(added.status,201);assert.equal(JSON.stringify(added.data).includes('synthetic-private-token'),false);assert.equal(JSON.stringify((await call('/api/state')).data).includes('synthetic-private-token'),false);assert.equal(JSON.stringify((await call('/api/export')).data).includes('synthetic-private-token'),false);});
function rediscoveryFixture(){let ownerCount=8,memberCount=1,missingOwnerFirst=false,fail=false;let calls=0;const actors=[];const calendar=(actor,index)=>'https://p01-caldav.icloud.com/'+(actor==='owner'?'111':'222')+'/calendars/calendar-'+index+'/';const fetcher=async(raw,init)=>{calls++;const username=atob(new Headers(init.headers).get('Authorization').slice(6)).split(':')[0],actor=username.startsWith('bella')?'member':'owner';actors.push(actor);if(fail)return new Response('',{status:401});const wrap=children=>'<d:multistatus xmlns:d="DAV:" xmlns:c="urn:ietf:params:xml:ns:caldav">'+children+'</d:multistatus>',entry=(href,props)=>'<d:response><d:href>'+href+'</d:href><d:propstat><d:prop>'+props+'</d:prop><d:status>HTTP/1.1 200 OK</d:status></d:propstat></d:response>';if(init.method==='REPORT'){const index=Number(String(raw).match(/calendar-(\d+)/)?.[1]);const day=new Date().toISOString().slice(0,10).replaceAll('-','');const ics=['BEGIN:VCALENDAR','VERSION:2.0','BEGIN:VEVENT','UID:rediscovery-'+actor+'-'+index,'DTSTART:'+day+'T120000Z','DTEND:'+day+'T130000Z','SUMMARY:Existing event '+index,'END:VEVENT','END:VCALENDAR'].join('\r\n');return new Response(wrap(entry(String(raw)+'event.ics','<c:calendar-data><![CDATA['+ics+']]></c:calendar-data>')),{status:207});}if(init.body.includes('current-user-principal'))return new Response(wrap(entry('/','<d:current-user-principal><d:href>/principal/</d:href></d:current-user-principal>')),{status:207});if(init.body.includes('calendar-home-set'))return new Response(wrap(entry('/','<c:calendar-home-set><d:href>https://p01-caldav.icloud.com/calendars/</d:href></c:calendar-home-set>')),{status:207});const rows=Array.from({length:actor==='owner'?ownerCount:memberCount},(_,index)=>index).filter(index=>actor!=='owner'||!missingOwnerFirst||index!==0).map(index=>entry(calendar(actor,index),'<d:displayname>'+actor+' calendar '+index+'</d:displayname><d:resourcetype><c:calendar/></d:resourcetype>')).join('');return new Response(wrap(rows),{status:207});};return{calendar,fetcher,actors,get calls(){return calls},set ownerCount(v){ownerCount=v},set memberCount(v){memberCount=v},set missingOwnerFirst(v){missingOwnerFirst=v},set fail(v){fail=v}};}
test('stored-credential rediscovery makes new ninth calendars selectable without changing existing imports, selections or feeds',async()=>{const apple=rediscoveryFixture(),feed=subscriptionFixture('discovery-feed');const{call,DB}=setup({HUB_ENCRYPTION_KEY:Buffer.alloc(32,81).toString('base64'),ICLOUD_FETCH:apple.fetcher,CALENDAR_FEED_FETCH:feed.fetcher,CALENDAR_FEED_RESOLVE:feed.resolve});await call('/api/icloud/connect','POST',{username:'owner@example.test',password:'synthetic-password'});const selected=Array.from({length:8},(_,i)=>apple.calendar('owner',i));await call('/api/icloud/calendars','POST',{calendarIds:selected});await call('/api/icloud/sync','POST',{});await call('/api/icloud/subscriptions','POST',{title:'Existing feed',url:feed.privateUrl});const saved=(await call('/api/icloud/status')).data,lastSuccess=saved.lastSuccess,encrypted=(await DB.prepare("SELECT credentials FROM hub_icloud_accounts WHERE user_id='owner'").first()).credentials;const records=(await call('/api/state')).data.records.filter(r=>r.kind==='calendar');apple.ownerCount=10;const discovered=await call('/api/icloud/discover','POST',{});assert.equal(discovered.status,200);assert.equal(discovered.data.discoveredCount,10);assert.equal(discovered.data.calendars.length,10);assert.deepEqual(discovered.data.selectedCalendarIds,selected);assert.equal(discovered.data.lastSuccess,lastSuccess);assert.equal(discovered.data.subscriptions[0].id,saved.subscriptions[0].id);assert.equal((await DB.prepare("SELECT credentials FROM hub_icloud_accounts WHERE user_id='owner'").first()).credentials,encrypted);assert.deepEqual(new Set((await call('/api/state')).data.records.filter(r=>r.kind==='calendar').map(r=>r.id)),new Set(records.map(r=>r.id)));const ninth=apple.calendar('owner',8);assert.equal(discovered.data.calendars.find(c=>c.id===ninth).available,true);await call('/api/icloud/calendars','POST',{calendarIds:[...selected,ninth]});assert.equal((await call('/api/icloud/sync','POST',{})).status,200);const previous=(await call('/api/icloud/status')).data;const priorIds=(await call('/api/state')).data.records.filter(r=>r.kind==='calendar').map(r=>r.id);apple.missingOwnerFirst=true;const missing=await call('/api/icloud/discover','POST',{});assert.equal(missing.status,200);assert.deepEqual(missing.data.selectedCalendarIds,[...selected,ninth]);assert.equal(missing.data.calendars.find(c=>c.id===selected[0]).available,false);assert.equal(missing.data.calendars.find(c=>c.id===selected[0]).lastKnown,true);assert.equal(missing.data.lastSuccess,previous.lastSuccess);assert.deepEqual(new Set((await call('/api/state')).data.records.filter(r=>r.kind==='calendar').map(r=>r.id)),new Set(priorIds));apple.missingOwnerFirst=false;const restored=await call('/api/icloud/discover','POST',{});assert.equal(restored.data.calendars.find(c=>c.id===selected[0]).available,true);assert.equal(restored.data.error,undefined);apple.fail=true;assert.equal((await call('/api/icloud/discover','POST',{})).status,502);assert.deepEqual(new Set((await call('/api/state')).data.records.filter(r=>r.kind==='calendar').map(r=>r.id)),new Set(priorIds));assert.equal((await call('/api/icloud/status')).data.lastSuccess,previous.lastSuccess);assert.equal((await DB.prepare("SELECT credentials FROM hub_icloud_accounts WHERE user_id='owner'").first()).credentials,encrypted);});

test('fixed calendar MCP tools require the owner and reject cross-site calls before feed access', async () => {
  const feed = subscriptionFixture('mcp-auth-feed');
  const {call, env} = setup({HUB_ENCRYPTION_KEY:Buffer.alloc(32,85).toString('base64'), CALENDAR_FEED_FETCH:feed.fetcher, CALENDAR_FEED_RESOLVE:feed.resolve});
  await call('/api/state');
  await call('/api/members','POST',{userId:'member',displayName:'Partner'});
  const invoke = async (name, who, origin) => {
    const headers = {'Content-Type':'application/json', ...(who ? {'oai-authenticated-user-id':who} : {}), ...(origin ? {Origin:origin} : {})};
    const response = await handleMcp(new Request('https://hub.test/mcp',{method:'POST',headers,body:JSON.stringify({jsonrpc:'2.0',id:1,method:'tools/call',params:{name,arguments:{title:'Requested sessions',url:feed.privateUrl}}})}),env);
    return {status:response.status,data:await response.json()};
  };
  for (const name of ['bird_hub_add_calendar_subscription','bird_hub_read_calendar_connections']) {
    assert.equal((await invoke(name)).status,401);
    assert.equal((await invoke(name,'stranger')).status,403);
    assert.equal((await invoke(name,'member')).status,403);
    assert.equal((await invoke(name,'owner','https://other.test')).status,403);
  }
  assert.equal(feed.calls,0);
});

test('calendar MCP adds an encrypted owner feed once, maps a profile and reads safe own metadata only', async () => {
  const feed = subscriptionFixture('mcp-requested-feed');
  const {call, DB, env} = setup({HUB_ENCRYPTION_KEY:Buffer.alloc(32,86).toString('base64'), CALENDAR_FEED_FETCH:feed.fetcher, CALENDAR_FEED_RESOLVE:feed.resolve});
  await call('/api/state');
  await call('/api/members','POST',{userId:'member',displayName:'Partner'});
  const paused = (await call('/api/items','POST',{kind:'source',data:{title:'Separate paused workflow',sourceId:'unrelated-weekly',adapter:'workflow',runStatus:'paused',schedulePaused:true,scheduleLabel:'Original paused schedule'}})).data.record;
  const profile = (await call('/api/items','POST',{kind:'profile',data:{name:'Calendar person',color:'#123456'}})).data.record;
  const invoke = async (name, args={}) => {
    const response = await handleMcp(new Request('https://hub.test/mcp',{method:'POST',headers:{'Content-Type':'application/json','oai-authenticated-user-id':'owner'},body:JSON.stringify({jsonrpc:'2.0',id:1,method:'tools/call',params:{name,arguments:args}})}),env);
    assert.equal(response.status,200);
    return (await response.json()).result;
  };
  const added = await invoke('bird_hub_add_calendar_subscription',{title:'Requested sessions '+feed.privateUrl,url:feed.privateUrl,personId:profile.id,userId:'member',headers:{Authorization:'must-not-forward'}});
  assert.equal(added.isError,false);
  assert.equal(added.structuredContent.importedCount,1);
  assert.equal(added.structuredContent.subscriptions[0].personId,profile.id);
  assert.equal(JSON.stringify(added).includes('synthetic-private-token'),false);
  const stored = await DB.prepare('SELECT user_id,encrypted_url FROM hub_calendar_subscriptions').first();
  assert.equal(stored.user_id,'owner');
  assert.equal(stored.encrypted_url.includes('synthetic-private-token'),false);
  const read = await invoke('bird_hub_read_calendar_connections',{userId:'member'});
  assert.equal(read.isError,false);
  assert.equal(read.structuredContent.scope,'self');
  assert.equal(read.structuredContent.configured,false); // Subscription-only account needs no Apple login.
  assert.equal(read.structuredContent.subscriptions.length,1);
  assert.equal(read.structuredContent.subscriptions[0].id,added.structuredContent.id);
  assert.equal(JSON.stringify(read).includes('synthetic-private-token'),false);
  assert.equal(JSON.stringify(read).includes('encrypted_url'),false);
  assert.equal((await call('/api/icloud/status','GET',undefined,{user:'member'})).data.subscriptions.length,0);
  const duplicate = await invoke('bird_hub_add_calendar_subscription',{title:'Retry',url:feed.privateUrl.replace('https:','webcal:')});
  assert.equal(duplicate.isError,true);
  assert.equal(duplicate.structuredContent.error.code,'duplicate_subscription');
  assert.equal(JSON.stringify(duplicate).includes('synthetic-private-token'),false);
  assert.equal(await DB.prepare('SELECT COUNT(*) AS n FROM hub_calendar_subscriptions').first().then(row=>row.n),1);
  const state = (await call('/api/state')).data;
  assert.equal(state.records.filter(record=>record.kind==='calendar').length,1);
  assert.deepEqual(state.records.find(record=>record.id===paused.id).data,paused.data);
});

test('calendar MCP preserves safe-fetch restrictions and never echoes rejected private links', async () => {
  const feed = subscriptionFixture('mcp-failed-feed');
  const {call,DB,env} = setup({HUB_ENCRYPTION_KEY:Buffer.alloc(32,87).toString('base64'), CALENDAR_FEED_FETCH:feed.fetcher, CALENDAR_FEED_RESOLVE:feed.resolve});
  await call('/api/state');
  const invoke = async url => {
    const response = await handleMcp(new Request('https://hub.test/mcp',{method:'POST',headers:{'Content-Type':'application/json','oai-authenticated-user-id':'owner'},body:JSON.stringify({jsonrpc:'2.0',id:1,method:'tools/call',params:{name:'bird_hub_add_calendar_subscription',arguments:{title:'Requested calendar',url}}})}),env);
    return (await response.json()).result;
  };
  for (const url of ['http://calendar.example.org/private.ics?token=synthetic-private-token','https://127.0.0.1/private.ics?token=synthetic-private-token','https://user:synthetic-private-token@calendar.example.org/private.ics']) {
    const result = await invoke(url);
    assert.equal(result.isError,true);
    assert.equal(JSON.stringify(result).includes('synthetic-private-token'),false);
  }
  assert.equal(feed.calls,0);
  feed.fail=true;
  const failed=await invoke(feed.privateUrl);
  assert.equal(failed.isError,true);
  assert.equal(JSON.stringify(failed).includes('synthetic-private-token'),false);
  assert.equal(await DB.prepare('SELECT COUNT(*) AS n FROM hub_calendar_subscriptions').first().then(row=>row.n),0);
});
test('calendar rediscovery uses only the authenticated member’s stored credentials',async()=>{const apple=rediscoveryFixture();const{call}=setup({HUB_ENCRYPTION_KEY:Buffer.alloc(32,82).toString('base64'),ICLOUD_FETCH:apple.fetcher});await call('/api/icloud/connect','POST',{username:'owner@example.test',password:'owner-password'});await call('/api/members','POST',{userId:'member',displayName:'Partner'});const actor={user:'member'};const before=apple.calls;assert.equal((await call('/api/icloud/discover','POST',{},actor)).status,409);assert.equal(apple.calls,before);await call('/api/icloud/connect','POST',{username:'bella@example.test',password:'member-password'},actor);apple.memberCount=2;const start=apple.actors.length;const own=await call('/api/icloud/discover','POST',{userId:'owner'},actor);assert.equal(own.status,200);assert.equal(own.data.calendars.length,2);assert.ok(own.data.calendars.every(c=>c.id.includes('/222/')));assert.ok(apple.actors.slice(start).every(value=>value==='member'));assert.equal((await call('/api/icloud/status')).data.calendars.length,8);assert.equal((await call('/api/icloud/discover','POST',{}, {user:'member',origin:'https://other.test'})).status,403);});

