 const added=await call('/api/icloud/subscriptions','POST',{title:'Requested feed',url:feed.privateUrl});const id=added.data.id;
 const other=await call('/api/icloud/subscriptions','POST',{title:'Member feed',url:feed.privateUrl+'&actor=member'},{user:'member'});
 const memberBefore=await DB.prepare("SELECT revision FROM hub_icloud_accounts WHERE user_id='member'").first();
 const invoke=async(args,actor='owner',origin)=>{const headers={'Content-Type':'application/json'};if(actor)headers['oai-authenticated-user-id']=actor;if(origin)headers.Origin=origin;const response=await handleMcp(new Request('https://hub.test/mcp',{method:'POST',headers,body:JSON.stringify({jsonrpc:'2.0',id:1,method:'tools/call',params:{name:'bird_hub_refresh_calendar',arguments:args}})}),env);return{status:response.status,data:await response.json()};};
 const start=actors.length;const refreshed=await invoke({source:'icloud'});assert.equal(refreshed.status,200);assert.equal(refreshed.data.result.isError,false);assert.equal(refreshed.data.result.structuredContent.status,'ready');assert.equal(refreshed.data.result.structuredContent.importedCount,2);assert.ok(actors.slice(start).every(name=>name==='owner@example.test'));assert.ok(actors.length>start);
 const feedBefore=feed.calls;const refreshedFeed=await invoke({source:'subscription',subscriptionId:id});assert.equal(refreshedFeed.data.result.isError,false);assert.equal(refreshedFeed.data.result.structuredContent.status,'ready');assert.equal(refreshedFeed.data.result.structuredContent.subscriptionId,id);assert.equal(feed.calls,feedBefore+1);
 const serialized=JSON.stringify([refreshed.data,refreshedFeed.data]);for(const privateText of ['synthetic-private-token','synthetic-app-password','owner@example.test','bella@example.test','encrypted_url',apple.calendars.owner])assert.equal(serialized.includes(privateText),false);
