// Synthetic JPEG framing and provider fixtures; these are not real food-recognition tests.
function fridgeJpeg(edge=640,size=34){const jpeg=new Uint8Array([255,216,255,192,0,11,8,1,224,edge>>8,edge&255,1,1,17,0,255,218,0,8,1,1,0,0,63,0,1,255,0,2,255,208,3,255,217]);if(size<=jpeg.length)return jpeg;const larger=new Uint8Array(size);larger.fill(49);larger.set(jpeg.subarray(0,-2));larger.set([255,217],size-2);return larger;}
function fridgeFixture(){const requests=[];let response;const token='synthetic-fridge-secret-'.repeat(3);const options={HUB_RECIPE_AI_URL:'https://fixture.fridge-account.workers.dev/infer',HUB_RECIPE_AI_TOKEN:token,FRIDGE_AI_FETCH:async(url,init)=>{requests.push({url,init,payload:JSON.parse(init.body)});if(response)return typeof response==='function'?response(url,init):response;const payload=requests.at(-1).payload;return Response.json(payload.operation==='recognize'?{ingredients:[{name:'Tomatoes',uncertain:false,photo:'must-not-return'}],warnings:[]}:{draft:{title:'Tomato skillet',servings:payload.servings,ingredients:[{name:'  TOMATOES  ',amount:2,unit:'whole'},{name:'Olive oil',amount:1,unit:'tbsp'}],instructions:'Cook the tomatoes in the oil.',photo:'must-not-return',sourceUrl:'https://invented.example.test'},missingIngredients:[],warnings:[]});}};const env=setup(options);const call=async(action,body,opts={})=>{const binary=body instanceof Uint8Array;const headers={'Content-Type':binary?'image/jpeg':'application/json','Origin':opts.origin??'https://hub.test','oai-authenticated-user-id':opts.user??'owner',...(opts.ack===false?{}:{'X-Fridge-Processing-Acknowledged':'true'}),...opts.headers};if(opts.anonymous)delete headers['oai-authenticated-user-id'];const request=new Request('https://hub.test/api/recipes/fridge/'+action,{method:body===undefined?'GET':'POST',headers,signal:opts.signal,body:body===undefined?undefined:binary?body:JSON.stringify(body)});const result=await handleApi(request,env.env);return{status:result.status,data:await result.json()};};return{...env,fridge:call,requests,token,set response(value){response=value;}};}

