test('a large cookbook leaves both calendar refresh paths usable and unrelated household records unchanged',async()=>{
 const apple=appleFixture(),feed=subscriptionFixture('capacity-subscription');
 const {call,DB,env}=setup({HUB_ENCRYPTION_KEY:Buffer.alloc(32,101).toString('base64'),ICLOUD_FETCH:apple.fetcher,CALENDAR_FEED_FETCH:feed.fetcher,CALENDAR_FEED_RESOLVE:feed.resolve});
 await call('/api/items','POST',{kind:'source',data:{title:'iCloud',sourceId:'icloud',adapter:'icloud'}});
 await call('/api/items','POST',{kind:'shopping',data:{title:'Synthetic groceries',done:true}});
 await call('/api/items','POST',{kind:'reminder',data:{title:'Synthetic household task',done:false}});
 const manual=(await call('/api/items','POST',{kind:'calendar',data:{title:'Synthetic manual plan',startAt:new Date().toISOString()}})).data.record;
 assert.equal((await call('/api/icloud/connect','POST',{username:'owner@example.test',password:'synthetic-app-password'})).status,200);
 assert.equal((await call('/api/icloud/calendars','POST',{calendarIds:[apple.calendar]})).status,200);
 assert.equal((await call('/api/icloud/sync','POST',{})).status,200);
 const added=await call('/api/icloud/subscriptions','POST',{title:'Synthetic subscribed sessions',url:feed.privateUrl});
 assert.equal(added.status,201);
 const subscriptionId=added.data.subscriptions[0].id;
 await seedSyntheticCookbook(DB,3500);
 const unrelated=await DB.prepare("SELECT * FROM hub_records WHERE kind NOT IN ('calendar','source') OR id=? ORDER BY id").bind(manual.id).all();
 const originalIds=(await call('/api/state')).data.records.filter(row=>row.kind==='calendar').map(row=>row.id).sort();
 const refresh=async args=>{
  const response=await handleMcp(new Request('https://hub.test/mcp',{method:'POST',headers:{'Content-Type':'application/json','oai-authenticated-user-id':'owner'},body:JSON.stringify({jsonrpc:'2.0',id:1,method:'tools/call',params:{name:'bird_hub_refresh_calendar',arguments:args}})}),env);
  const result=await response.json();
  assert.equal(response.status,200);
  assert.equal(result.result.isError,false,JSON.stringify(result));
  assert.equal(result.result.structuredContent.importedCount,1);
 };
 for(let round=0;round<2;round++){
  await refresh({source:'icloud'});
  await refresh({source:'subscription',subscriptionId});
 }
 const state=await call('/api/state');
 assert.equal(state.status,200);
 assert.equal(state.data.records.filter(row=>row.kind==='recipe').length,3500);
 assert.equal(state.data.records.find(row=>row.kind==='recipe').data.summaryOnly,true);
 assert.equal(state.data.records.find(row=>row.kind==='recipe').data.instructions,undefined);
 assert.deepEqual(state.data.records.filter(row=>row.kind==='calendar').map(row=>row.id).sort(),originalIds);
 assert.deepEqual(await DB.prepare("SELECT * FROM hub_records WHERE kind NOT IN ('calendar','source') OR id=? ORDER BY id").bind(manual.id).all(),unrelated);
 const status=(await call('/api/icloud/status')).data;
 assert.equal(status.status,'ready');
 assert.equal(status.subscriptions[0].status,'ready');
 assert.ok(status.lastSuccess&&status.subscriptions[0].lastSuccess);
});

test('calendar admission and the shared reader agree at the exact record bound and reject one more without partial writes',async()=>{
 const {snapshot,commitStore}=await import('../server/icloud-store.ts');
 const {call,DB}=setup();await call('/api/state');
 await seedSyntheticCookbook(DB,MAX_HOUSEHOLD_RECORDS-2);
 const now=new Date().toISOString();
 // Retained old manual rows can lack origin; they still occupy one household record.
 await DB.prepare("INSERT INTO hub_records(id,kind,data,version,created_at,updated_at,updated_by) VALUES('capacity_legacy_manual','calendar',?,1,?,?,'owner')").bind(JSON.stringify({title:'Synthetic legacy manual plan',startAt:now,endAt:now}),now,now).run();
 const contribution=index=>({contribution_key:'capacity_contribution_'+index,user_id:'owner',calendar_id:'synthetic_calendar',provider_id:'synthetic_provider_'+index,event_key:String(index).padStart(64,'0'),record_id:'capacity_imported_'+index,data:JSON.stringify({title:'Synthetic imported event '+index,startAt:now,endAt:now,origin:'icloud'}),updated_at:now});
 await commitStore({db:DB,before:await snapshot(DB),contributions:[contribution(1)],userId:'owner'});
 const exact=await call('/api/state');
 assert.equal(exact.status,200);
 assert.equal(exact.data.records.length,MAX_HOUSEHOLD_RECORDS);
 const before=await snapshot(DB),operationsBefore=(await DB.prepare('SELECT COUNT(*) AS n FROM hub_operations').first()).n;
 await assert.rejects(commitStore({db:DB,before,contributions:[...before.contributions,contribution(2)],userId:'owner'}),error=>error.code==='household_capacity'&&error.status===413);
 assert.deepEqual(await snapshot(DB),before);
 assert.equal((await DB.prepare('SELECT COUNT(*) AS n FROM hub_operations').first()).n,operationsBefore);
 assert.equal((await DB.prepare('SELECT COUNT(*) AS n FROM hub_records').first()).n,MAX_HOUSEHOLD_RECORDS);
 await DB.prepare("INSERT INTO hub_records(id,kind,data,version,created_at,updated_at,updated_by) VALUES('capacity_overflow_fixture','shopping','{\"title\":\"Synthetic overflow\"}',1,?,?,'owner')").bind(now,now).run();
 const overflow=await call('/api/state');
 assert.equal(overflow.status,503);
 assert.equal(overflow.data.error.code,'record_limit');
});

test('failed provider reads can record honest source health above the shared record bound without replacing saved events',async()=>{
 const apple=appleFixture(),feed=subscriptionFixture('capacity-failure-subscription');
 const {call,DB}=setup({HUB_ENCRYPTION_KEY:Buffer.alloc(32,102).toString('base64'),ICLOUD_FETCH:apple.fetcher,CALENDAR_FEED_FETCH:feed.fetcher,CALENDAR_FEED_RESOLVE:feed.resolve});
 assert.equal((await call('/api/icloud/connect','POST',{username:'owner@example.test',password:'synthetic-app-password'})).status,200);
 assert.equal((await call('/api/icloud/calendars','POST',{calendarIds:[apple.calendar]})).status,200);
 assert.equal((await call('/api/icloud/sync','POST',{})).status,200);
 assert.equal((await call('/api/icloud/subscriptions','POST',{title:'Synthetic failing sessions',url:feed.privateUrl})).status,201);
 const previous=(await call('/api/icloud/status')).data;
 await seedSyntheticCookbook(DB,MAX_HOUSEHOLD_RECORDS);
 const records=await DB.prepare('SELECT * FROM hub_records ORDER BY id').all();
 assert.equal(records.results.length,MAX_HOUSEHOLD_RECORDS+2);
 apple.fail=true;feed.fail=true;
 assert.equal((await call('/api/icloud/sync','POST',{})).status,502);
 assert.equal((await call('/api/icloud/subscriptions/'+previous.subscriptions[0].id+'/sync','POST',{})).status,502);
 const failed=(await call('/api/icloud/status')).data;
 assert.equal(failed.status,'error');
 assert.equal(failed.lastSuccess,previous.lastSuccess);
 assert.equal(failed.subscriptions[0].status,'error');
 assert.equal(failed.subscriptions[0].lastSuccess,previous.subscriptions[0].lastSuccess);
 assert.ok(failed.error&&failed.subscriptions[0].error);
 assert.deepEqual(await DB.prepare('SELECT * FROM hub_records ORDER BY id').all(),records);
});

function recipePhotoBucket(){const files=new Map();let puts=0;return{files,get puts(){return puts;},async head(key){const bytes=files.get(key);return bytes?{key,size:bytes.length}:null;},async put(key,data){puts++;files.set(key,new Uint8Array(data));return{key};},async get(key){const data=files.get(key);if(!data)return null;return{body:new Response(data).body,arrayBuffer:async()=>data.slice().buffer};},async delete(key){files.delete(key);}};}
const tinyRecipeWebp=()=>Buffer.from('UklGRiIAAABXRUJQVlA4IBYAAAAwAQCdASoBAAEADsD+JaQAA3AAAAAA','base64');

test('dish thumbnails enforce owner writes, private household reads and compact metadata while deduplicating objects',async()=>{
 const bucket=recipePhotoBucket(),{call,env,DB}=setup({BUCKET:bucket});const one=(await call('/api/items','POST',{kind:'recipe',data:recipe})).data.record,two=(await call('/api/items','POST',{kind:'recipe',data:{...recipe,title:'Another soup'}})).data.record;
 const payload={recipeId:one.id,version:one.version,imageBase64:tinyRecipeWebp().toString('base64')};
 assert.equal((await call('/api/recipes/photos-import','POST',{entries:[payload]},{anonymous:true})).status,401);
 await call('/api/members','POST',{userId:'family-photo-reader',displayName:'Family'});
 assert.equal((await call('/api/recipes/photos-import','POST',{entries:[payload]},{user:'family-photo-reader'})).status,403);
 const first=await call('/api/recipes/photos-import','POST',{entries:[payload,{...payload,recipeId:two.id}]});assert.equal(first.status,200);assert.equal(first.data.results.length,2);assert.equal(bucket.puts,1);assert.equal(first.data.results[0].photo.bytes,42);
 const again=await call('/api/recipes/photos-import','POST',{entries:[payload]});assert.equal(again.data.results[0].unchanged,true);assert.equal(bucket.puts,1);
 const state=(await call('/api/state')).data;const photo=state.records.find(r=>r.id===one.id).data.photo;assert.equal(photo.width,1);assert.ok(photo.url.startsWith('/api/recipes/'+one.id+'/photo?v='));assert.equal(JSON.stringify(state).includes(payload.imageBase64),false);assert.equal((await call('/api/items/'+one.id)).data.record.data.photo.sha256,photo.sha256);
 const raw=async(user)=>handleApi(new Request('https://hub.test'+photo.url,{headers:user?{'oai-authenticated-user-id':user}:{}}),env);assert.equal((await raw()).status,401);assert.equal((await raw('outsider')).status,403);const image=await raw('family-photo-reader');assert.equal(image.status,200);assert.equal(image.headers.get('Cache-Control'),'private, max-age=3600');assert.equal(image.headers.get('Content-Type'),'image/webp');assert.equal((await image.arrayBuffer()).byteLength,42);
 assert.equal((await call('/api/recipes/photos-status',undefined,undefined,{user:'family-photo-reader'})).status,403);const status=await call('/api/recipes/photos-status');assert.equal(status.data.photoCount,2);assert.equal(status.data.objectCount,1);assert.equal(status.data.bytes,42);
 assert.equal((await DB.prepare('SELECT data FROM hub_records WHERE id=?').bind(one.id).first()).data.includes('imageBase64'),false);
});

test('thumbnail image validation bounds dimensions, batch bytes, metadata and versions before changing mappings',async()=>{
 const{validateRecipePhoto}=await import('../server/recipe-photos.ts');const bucket=recipePhotoBucket(),{call,DB}=setup({BUCKET:bucket});const row=(await call('/api/items','POST',{kind:'recipe',data:recipe})).data.record;
 const payload={recipeId:row.id,version:1,imageBase64:tinyRecipeWebp().toString('base64')};const path='/api/recipes/photos-import';
 assert.equal((await call(path,'POST',{entries:[{...payload,version:2}]})).status,409);assert.equal(bucket.puts,0);
 assert.equal((await call(path,'POST',{entries:Array.from({length:21},()=>payload)})).status,400);
 const wide=tinyRecipeWebp();wide.writeUInt16LE(481,26);assert.throws(()=>validateRecipePhoto(wide),e=>e.code==='recipe_photo_too_large');
 const metadata=Buffer.concat([tinyRecipeWebp(),Buffer.from('EXIF\x02\x00\x00\x00xx','binary')]);metadata.writeUInt32LE(metadata.length-8,4);assert.throws(()=>validateRecipePhoto(metadata),e=>e.code==='invalid_recipe_photo');
 const large=Buffer.alloc(20_000);tinyRecipeWebp().copy(large);large.writeUInt32LE(large.length-8,4);large.writeUInt32LE(large.length-20,16);const batch=Array.from({length:7},()=>({...payload,imageBase64:large.toString('base64')}));assert.equal((await call(path,'POST',{entries:batch})).status,413);assert.equal(bucket.puts,0);assert.equal((await DB.prepare('SELECT COUNT(*) AS n FROM hub_recipe_photos').first()).n,0);
 assert.equal((await call(path,'POST',{entries:[payload]})).status,200);const changed=tinyRecipeWebp();changed[changed.length-1]=1;const next={...payload,imageBase64:changed.toString('base64')};assert.equal((await call(path,'POST',{entries:[next]})).status,409);assert.equal(bucket.puts,1);assert.equal((await call(path,'POST',{entries:[{...next,photoVersion:1}]})).status,200);assert.equal((await call('/api/items/'+row.id)).data.record.version,1);
});

test('temporary thumbnail migration grant is disabled by default, requires existing owner and only changes existing recipe photos',async()=>{
 const token='synthetic-temporary-photo-grant-1234567890';const bucket=recipePhotoBucket(),fresh=setup({BUCKET:bucket,HUB_RECIPE_PHOTO_IMPORT_TOKEN:token});
 const request=(env,data,key=token)=>handleApi(new Request('https://hub.test/api/recipes/photos-migration',{method:'POST',headers:{'Content-Type':'application/json','X-Bird-Recipe-Import':key},body:JSON.stringify(data)}),env);
 assert.equal((await request(fresh.env,{entries:[]})).status,403);assert.equal((await fresh.DB.prepare('SELECT COUNT(*) AS n FROM hub_owner').first()).n,0);
 const{call,env}=setup({BUCKET:bucket});const recipeRow=(await call('/api/items','POST',{kind:'recipe',data:recipe})).data.record;const payload={recipeId:recipeRow.id,version:1,imageBase64:tinyRecipeWebp().toString('base64')};
 assert.equal((await request(env,{entries:[payload]})).status,404);env.HUB_RECIPE_PHOTO_IMPORT_TOKEN=token;assert.equal((await request(env,{entries:[payload]},'wrong-grant')).status,403);
 assert.equal((await request(env,{entries:[{...payload,recipeId:'does_not_exist'}]})).status,404);
 const r=await request(env,{entries:[payload]});assert.equal(r.status,200);const receipts=await r.json();assert.equal(receipts.results[0].verified,true);assert.equal(receipts.results[0].photo.bytes,42);
 const verified=await request(env,{verify:[recipeRow.id]});assert.equal((await verified.json()).results[0].sha256,receipts.results[0].photo.sha256);
 delete env.HUB_RECIPE_PHOTO_IMPORT_TOKEN;assert.equal((await request(env,{verify:[recipeRow.id]})).status,404);
});

test('migration processes distinct recipes with at most four concurrent workers, stable receipt order and shared-object replay safety',async()=>{
 const bucket=recipePhotoBucket();let active=0,maxActive=0;const get=bucket.get.bind(bucket);bucket.get=async key=>{active++;maxActive=Math.max(maxActive,active);await new Promise(resolve=>setImmediate(resolve));const file=await get(key);return file?{...file,arrayBuffer:async()=>{try{await new Promise(resolve=>setImmediate(resolve));return await file.arrayBuffer();}finally{active--;}}}:null;};
 const token='synthetic-bounded-thumbnail-grant-123456';const {call,env,DB}=setup({BUCKET:bucket,HUB_RECIPE_PHOTO_IMPORT_TOKEN:token});const rows=[];for(let i=0;i<9;i++)rows.push((await call('/api/items','POST',{kind:'recipe',data:{...recipe,title:'Concurrent thumbnail '+i}})).data.record);
 const entries=rows.map(row=>({recipeId:row.id,version:row.version,imageBase64:tinyRecipeWebp().toString('base64')}));
 const invoke=()=>handleApi(new Request('https://hub.test/api/recipes/photos-migration',{method:'POST',headers:{'Content-Type':'application/json','X-Bird-Recipe-Import':token},body:JSON.stringify({entries})}),env);
 const first=await invoke();assert.equal(first.status,200);const initial=await first.json();assert.deepEqual(initial.results.map(r=>r.recipeId),rows.map(r=>r.id));assert.ok(initial.results.every(r=>r.verified));assert.ok(maxActive>1);assert.ok(maxActive<=4);assert.equal(active,0);assert.equal(bucket.files.size,1);assert.equal((await DB.prepare('SELECT COUNT(*) AS n FROM hub_recipe_photos').first()).n,rows.length);
 const second=await invoke();assert.equal(second.status,200);const replay=await second.json();assert.deepEqual(replay.results.map(r=>r.recipeId),rows.map(r=>r.id));assert.ok(replay.results.every(r=>r.unchanged&&r.verified));assert.equal(bucket.files.size,1);assert.equal((await DB.prepare('SELECT COUNT(*) AS n FROM hub_recipe_photos').first()).n,rows.length);
});
